ystem-mcq-part-2">Operating System MCQ Part 2</a></li><li class="leftmenu"><a href="/computer-graphics-mcq">Computer Graphics MCQ</a></li><li class="leftmenu"><a href="/css-mcq">CSS MCQ</a></li><li class="leftmenu"><a href="/python-mcq">Python MCQ</a></li><li class="leftmenu"><a href="/python-mcq-part-2">Python MCQ Part 2</a></li><li class="leftmenu"><a href="/cpp-mcq">C++ MCQ</a></li><li class="leftmenu"><a href="/cpp-mcq-part-2">C++ MCQ Part 2</a></li><li class="leftmenu"><a href="/digital-electronics-mcq">Digital Electronics MCQ</a></li><li class="leftmenu"><a href="/oops-mcq">OOPS MCQ</a></li><li class="leftmenu"><a href="/javascript-mcq">JavaScript MCQ</a></li><li class="leftmenu"><a href="/c-language-mcq">C language MCQ</a></li><li class="leftmenu"><a href="/c-language-mcq-part-2">C language MCQ Part-2</a></li><li class="leftmenu"><a href="/dbms-mcq">DBMS MCQ</a></li><li class="leftmenu"><a href="/software-engineering-mcq">Software Engineering MCQ</a></li><li class="leftmenu"><a href="/computer-fundamental-mcq">Computer Fundamental MCQ</a></li><li class="leftmenu"><a href="/computer-fundamental-mcq-part-2">Computer Fundamental MCQ Part 2</a></li><li class="leftmenu"><a href="/sql-mcq">SQL MCQ</a></li><li class="leftmenu"><a href="/data-mining-mcq">Data Mining MCQ</a></li><li class="leftmenu"><a href="/artificial-intelligence-mcq">Artificial Intelligence MCQ</a></li><li class="leftmenu"><a href="/data-structure-mcq">Data Structure MCQ</a></li><li class="leftmenu"><a href="/discrete-mathematics-mcq">Discrete Mathematics MCQ</a></li><li class="leftmenu"><a href="/html-mcq">HTML MCQ</a></li><li class="leftmenu"><a href="/python-mcq">Python MCQ</a></li><li class="leftmenu"><a href="/java-mcq">Java MCQ</a></li><li class="leftmenu"><a href="/thread-priority-mcqs-in-java">Thread Priority MCQs in Java</a></li><li class="leftmenu"><a href="/english-grammar-mcq-for-competitive-exam">English Grammar MCQ For Competitive Exam</a></li><li class="leftmenu"><a href="/java-multithreading-mcqs">Java Multithreading MCQs</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><div id="city"><table><tbody><tr><td><div id="bottomnextup"><a class="next" href="dbms-tutorial">next →</a> <a class="next" href="dbms-sql-cursors">← prev</a></div><h1 class="h1">DBMS MCQ</h1><div style="font-size:14px;margin-top:5px;margin-bottom:5px;color:#6f6e6e"><span>26 Apr 2025</span> | <span><i aria-hidden="true" class="fa fa-clock-o"></i> 17 min read</span></div><p>This section of interview questions and answers focuses on "Database Management System". One shall practice these interview questions to improve their concepts for various interviews such as campus interviews, walk-in interviews, company interviews, placements, entrance exams and other competitive exams.</p><p class="pq">1) Which of the following is generally used for performing tasks like creating the structure of the relations, deleting relation?</p><ol class="pointsa"><li>DML(Data Manipulation Language)</li><li>Query</li><li>Relational Schema</li><li>DDL(Data Definition Language)</li></ol><button class="showanswer" onclick="showhide(1)"><span id="btntext1">Show Answer</span></button><button class="workspace" onclick="showworkspace(1)"><span id="btntext1">Workspace</span></button><div id="workspace1"> </div><div class="testanswer" id="answer1"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The term "DDL" stands for Data Definition Language, used to perform all other essential tasks such as deleting relation and related schemas in defining the structure relation.</p></div><hr/><p class="pq">2) Which of the following provides the ability to query information from the database and insert tuples into, delete tuples from, and modify tuples in the database?</p><ol class="pointsa"><li>DML(Data Manipulation Language)</li><li>DDL(Data Definition Language)</li><li>Query</li><li>Relational Schema</li></ol><button class="showanswer" onclick="showhide(2)"><span id="btntext2">Show Answer</span></button><button class="workspace" onclick="showworkspace(2)"><span id="btntext2">Workspace</span></button><div id="workspace2"> </div><div class="testanswer" id="answer2"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The term "DML" stands for the Data Manipulation Language used to perform the required changes in the relation's values.</p></div><hr/><p class="pq">3) The given Query can also be replaced with_______:</p><div class="codeblock"><textarea class="xml" name="code">   SELECT name, course_id
   FROM instructor, teaches
   WHERE instructor_ID= teaches_ID;
</textarea></div><ol class="pointsa"><li>Select name,course_id from teaches,instructor where instructor_id=course_id;</li><li>Select name, course_id from instructor natural join teaches;</li><li>Select name, course_id from instructor;</li><li>Select course_id from instructor join teaches;</li></ol><button class="showanswer" onclick="showhide(3)"><span id="btntext3">Show Answer</span></button><button class="workspace" onclick="showworkspace(3)"><span id="btntext3">Workspace</span></button><div id="workspace3"> </div><div class="testanswer" id="answer3"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> Join clause joins two tables by matching the common column</p></div><hr/><p class="pq">4) Which one of the following given statements possibly contains the error?</p><ol class="pointsa"><li>select * from emp where empid = 10003;</li><li>select empid from emp where empid = 10006;</li><li>select empid from emp;</li><li>select empid where empid = 1009 and Lastname = 'GELLER';</li></ol><button class="showanswer" onclick="showhide(4)"><span id="btntext4">Show Answer</span></button><button class="workspace" onclick="showworkspace(4)"><span id="btntext4">Workspace</span></button><div id="workspace4"> </div><div class="testanswer" id="answer4"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The Query given in option D does not contain the "from" clause, which specifies the relation from which the values have to be selected or fetched. Therefore the correct answer is D.</p></div><hr/><p class="pq">5) Ready the Query carefully:</p><div class="codeblock"><textarea class="xml" name="code">SELECT emp_name
FROM department
WHERE dept_name LIKE ' _____ Computer Science';
</textarea></div><p>In the above-given Query, which of the following can be placed in the Query's blank portion to select the "dept_name" that also contains Computer Science as its ending string?</p><ol class="pointsa"><li>&amp;</li><li>_</li><li>%</li><li>$</li></ol><button class="showanswer" onclick="showhide(5)"><span id="btntext5">Show Answer</span></button><button class="workspace" onclick="showworkspace(5)"><span id="btntext5">Workspace</span></button><div id="workspace5"> </div><div class="testanswer" id="answer5"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In the above-given Query, the "%" (like) operator will be used, which is generally used while searching for a certain pattern in the strings. It represents the single and multiple characters. In this case, it used with "Where "louse to select the "dept_name" that contains the Computer Since as its ending string. To understand it more clearly, consider the following syntax:</p><p><strong>Syntax</strong></p><pre>
SELECT column1, column2, ...
FROM table_name
WHERE columnN LIKE pattern;
</pre></div><hr/><p class="pq">6) What do you mean by one to many relationships?</p><ol class="pointsa"><li>One class may have many teachers</li><li>One teacher can have many classes</li><li>Many classes may have many teachers</li><li>Many teachers may have many classes</li></ol><button class="showanswer" onclick="showhide(6)"><span id="btntext6">Show Answer</span></button><button class="workspace" onclick="showworkspace(6)"><span id="btntext6">Workspace</span></button><div id="workspace6"> </div><div class="testanswer" id="answer6"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> We can understand the "one to many" relationship as a teacher who may have more than one class to attend.</p></div><hr/><p class="pq">7) In the following Query, which of the following can be placed in the Query's blank portion to display the salary from highest to lowest amount, and sorting the employs name alphabetically?</p><div class="codeblock"><textarea class="xml" name="code">SELECT *
FROM instructor
ORDER BY salary ____, name ___;
</textarea></div><ol class="pointsa"><li>Ascending, Descending</li><li>Asc, Desc</li><li>Desc, Asc</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(7)"><span id="btntext7">Show Answer</span></button><button class="workspace" onclick="showworkspace(7)"><span id="btntext7">Workspace</span></button><div id="workspace7"> </div><div class="testanswer" id="answer7"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> To sort the salary from highest to lowest amount and display the employee's name alphabetically, one can use the "Desc and Asc" in the above-given Query.</p></div><hr/><p class="pq">8) The given Query can be replaced with ____________:</p><div class="codeblock"><textarea class="xml" name="code">SELECT name
FROM instructor1
WHERE salary &lt;= 100000 AND salary &gt;= 90000;
</textarea></div><p>a.</p><div class="codeblock"><textarea class="xml" name="code">SELECT name
FROM instructor1
WHERE salary BETWEEN 100000 AND 90000
</textarea></div><p>b.</p><div class="codeblock"><textarea class="xml" name="code">SELECT name
FROM instructor|
WHERE salary BETWEEN 90000 AND 100000;
</textarea></div><p>c.</p><div class="codeblock"><textarea class="xml" name="code">SELECT name
FROM instructor1
WHERE salary BETWEEN 90000 AND 100000;
</textarea></div><p>d.</p><div class="codeblock"><textarea class="xml" name="code">SELECT name
FROM instructor!
WHERE salary &lt;= 90000 AND salary&gt;=100000;
</textarea></div><br><button class="showanswer" onclick="showhide(8)"><span id="btntext8">Show Answer</span></button><button class="workspace" onclick="showworkspace(8)"><span id="btntext8">Workspace</span></button><div id="workspace8"> </div><div class="testanswer" id="answer8"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> The "SQL" contains a comparison known as the "BETWEEN," which is also used in one of the given queries, as you can see. The "BETWEEN" operator is generally used to simplify the "WHERE" clause that is used to specify that the value is greater than one value or greater than some values, less than one or more values.</p></div><hr/><p class="pq">9) A Database Management System is a type of _________software.</p><ol class="pointsa"><li>It is a type of system software</li><li>It is a kind of application software</li><li>It is a kind of general software</li><li>Both A and C</li></ol><button class="showanswer" onclick="showhide(9)"><span id="btntext9">Show Answer</span></button><button class="workspace" onclick="showworkspace(9)"><span id="btntext9">Workspace</span></button><div id="workspace9"> </div><div class="testanswer" id="answer9"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The DBMS (or Database Management System) is a kind of system software used for several operations such as creating tables/databases, storing data, managing databases. It also allows modifying the data stored in the database as well.</p></div><hr/><p class="pq">10) The term "FAT" is stands for_____</p><ol class="pointsa"><li>File Allocation Tree</li><li>File Allocation Table</li><li>File Allocation Graph</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(10)"><span id="btntext10">Show Answer</span></button><button class="workspace" onclick="showworkspace(10)"><span id="btntext10">Workspace</span></button><div id="workspace10"> </div><div class="testanswer" id="answer10"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The term "FAT" can be described as a file structure (or file architecture). In which all the information about the files where they are stored and where all these files need to be stored or in which directory, all that information generally stored in the file structure. Therefore the Operating system creates a table in which all the files and clusters are stored, known as the file allocation table.</p></div><hr/><p class="pq">11) Which of the following can be considered as the maximum size that is supported by FAT?</p><ol class="pointsa"><li>8GB</li><li>4GB</li><li>4TB</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(11)"><span id="btntext11">Show Answer</span></button><button class="workspace" onclick="showworkspace(11)"><span id="btntext11">Workspace</span></button><div id="workspace11"> </div><div class="testanswer" id="answer11"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The files with a size of less than 4 GB or equal to 4GB are easily supported by the FAT. All files with a size greater than the maximum size (or is 4Gb) are not supported by the FAT.</p></div><hr/><p class="pq">12) The term "NTFS" refers to which one of the following?</p><ol class="pointsa"><li>New Technology File System</li><li>New Tree File System</li><li>New Table type File System</li><li>Both A and C</li></ol><button class="showanswer" onclick="showhide(12)"><span id="btntext12">Show Answer</span></button><button class="workspace" onclick="showworkspace(12)"><span id="btntext12">Workspace</span></button><div id="workspace12"> </div><div class="testanswer" id="answer12"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> In the old operating systems, the file structure used to store and manage files is called the FAT 32 ( or File Allocation Table). Later, when the technology evolves with time, a new type of file system is introduced, known as the New Technology File System. It overcomes all the drawbacks, issues that exist in FAT file architecture and has many other new features such as it is fast, it can handle files whose size is even greater than 4 GB.</p></div><hr/><p class="pq">13) Which of the following can be considered as the maximum size that is supported by NTFS?</p><ol class="pointsa"><li>4GB</li><li>16TB</li><li>64TB</li><li>8TB</li></ol><button class="showanswer" onclick="showhide(13)"><span id="btntext13">Show Answer</span></button><button class="workspace" onclick="showworkspace(13)"><span id="btntext13">Workspace</span></button><div id="workspace13"> </div><div class="testanswer" id="answer13"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The New Technology File System was introduced in 1993 for the very first time as a part of new Windows operating systems (Windows NT 3.1).</p><p>You may be surprised to know that windows are still using it because of its fast speed and can support files whose size is up to 16TB (16 terabytes), which is much more than that file size supported by the old system.</p></div><hr/><p class="pq">14) A huge collection of the information or data accumulated form several different sources is known as ________:</p><ol class="pointsa"><li>Data Management</li><li>Data Mining</li><li>Data Warehouse</li><li>Both B and C</li></ol><button class="showanswer" onclick="showhide(14)"><span id="btntext14">Show Answer</span></button><button class="workspace" onclick="showworkspace(14)"><span id="btntext14">Workspace</span></button><div id="workspace14"> </div><div class="testanswer" id="answer14"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> A huge collection of different types of data/information which collected from many different sources stored in one place is called a data warehouse. It works just like the standard warehouse, which is generally a type of holding area/building to store the different types of different goods in huge quantities until they are further distributed. Therefore the correct answer is Data Warehouse.</p></div><hr/><p class="pq">15) Which of the following can be used to extract or filter the data &amp; information from the data warehouse?</p><ol class="pointsa"><li>Data redundancy</li><li>Data recovery tool</li><li>Data mining</li><li>Both B and C</li></ol><button class="showanswer" onclick="showhide(15)"><span id="btntext15">Show Answer</span></button><button class="workspace" onclick="showworkspace(15)"><span id="btntext15">Workspace</span></button><div id="workspace15"> </div><div class="testanswer" id="answer15"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> The tools used to obtain meaningful information or Data from the large collection of data (or from the Data Warehouses) are known as the Data mining tools. Through data mining, one can easily filter the useful information or data from the massive collection of the data. Therefore the correct answer is Data Mining.</p></div><hr/><p class="pq">16) Which one of the following refers to the copies of the same data (or information) occupying the memory space at multiple places.</p><ol class="pointsa"><li>Data Repository</li><li>Data Inconsistency</li><li>Data Mining</li><li>Data Redundancy</li></ol><button class="showanswer" onclick="showhide(16)"><span id="btntext16">Show Answer</span></button><button class="workspace" onclick="showworkspace(16)"><span id="btntext16">Workspace</span></button><div id="workspace16"> </div><div class="testanswer" id="answer16"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The data redundancy generally occurs whenever more than one copy of the exact same data exists in several different places. Sometimes it may cause data inconsistency, which can result in an unreliable source of data or information that is not good for anyone.</p></div><hr/><p class="pq">17) Which one of the following refers to the "data about data"?</p><ol class="pointsa"><li>Directory</li><li>Sub Data</li><li>Warehouse</li><li>Meta Data</li></ol><button class="showanswer" onclick="showhide(17)"><span id="btntext17">Show Answer</span></button><button class="workspace" onclick="showworkspace(17)"><span id="btntext17">Workspace</span></button><div id="workspace17"> </div><div class="testanswer" id="answer17"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The Mata Data refers to the type of data that describes the other data or information.</p><p>A general file or document is nothing more than a sequence of bytes that contains information like file name, file size, and date &amp; time when the document was created or modified.</p><p><strong>To understand it in more details, consider the following example:</strong></p><p>For a common music file, the metadata may include the singer's name, the year it was released, and the lyrics, etc.</p></div><hr/><p class="pq">18) Which of the following refers to the level of data abstraction that describes exactly how the data actually stored?</p><ol class="pointsa"><li>Conceptual Level</li><li>Physical Level</li><li>File Level</li><li>Logical Level</li></ol><button class="showanswer" onclick="showhide(18)"><span id="btntext18">Show Answer</span></button><button class="workspace" onclick="showworkspace(18)"><span id="btntext18">Workspace</span></button><div id="workspace18"> </div><div class="testanswer" id="answer18"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> Data abstraction means displaying or sharing only the data that is needed and hiding from all other data until it is necessary to share it. However, the data abstraction level that describes how the data was actually stored in the user's machine (or system) is known as the Physical level. Therefore the correct answer is B.</p></div><hr/><p class="pq">19) To which of the following the term "DBA" referred?</p><ol class="pointsa"><li>Data Bank Administrator</li><li>Database Administrator</li><li>Data Administrator</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(19)"><span id="btntext19">Show Answer</span></button><button class="workspace" onclick="showworkspace(19)"><span id="btntext19">Workspace</span></button><div id="workspace19"> </div><div class="testanswer" id="answer19"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The term "DBA" refers to the Database Administrator that manages the whole database and updates the database on a regular basis. In short, the database administrator has the responsibility of the whole database and to maintain it in an optimal &amp; stable state.</p></div><hr/><p class="pq">20) In general, a file is basically a collection of all related______.</p><ol class="pointsa"><li>Rows &amp; Columns</li><li>Fields</li><li>Database</li><li>Records</li></ol><button class="showanswer" onclick="showhide(20)"><span id="btntext20">Show Answer</span></button><button class="workspace" onclick="showworkspace(20)"><span id="btntext20">Workspace</span></button><div id="workspace20"> </div><div class="testanswer" id="answer20"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> Whenever we have some related data, information or records, we collect all those related data (or records), put them together, store them in one place, and give that collection a name that is known as a file.</p></div><hr/><p class="pq">21) The term "Data" refers to:</p><ol class="pointsa"><li>The electronic representation of the information( or data)</li><li>Basic information</li><li>Row Facts and figures</li><li>Both A and C</li></ol><button class="showanswer" onclick="showhide(21)"><span id="btntext21">Show Answer</span></button><button class="workspace" onclick="showworkspace(21)"><span id="btntext21">Workspace</span></button><div id="workspace21"> </div><div class="testanswer" id="answer21"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In general, the term "data" refers to the row facts and figure, whereas the information referred to as the data, which is really important for someone or a particular person. Therefore the correct answer is C.</p></div><hr/><p class="pq">22) Rows of a relation are known as the _______.</p><ol class="pointsa"><li>Degree</li><li>Tuples</li><li>Entity</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(22)"><span id="btntext22">Show Answer</span></button><button class="workspace" onclick="showworkspace(22)"><span id="btntext22">Workspace</span></button><div id="workspace22"> </div><div class="testanswer" id="answer22"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> In SQL, the relation is represented by a table, and a table is a collection of rows and columns. Therefore the collection of rows &amp; columns is called the table, whereas a table is known as the relation in the SQL. So in a relation (or we can say table), rows are called the tuples. So, the correct answer will be tuples.</p></div><hr/><p class="pq">23) Which of the following refers to the number of tuples in a relation?</p><ol class="pointsa"><li>Entity</li><li>Column</li><li>Cardinality</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(23)"><span id="btntext23">Show Answer</span></button><button class="workspace" onclick="showworkspace(23)"><span id="btntext23">Workspace</span></button><div id="workspace23"> </div><div class="testanswer" id="answer23"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> Cardinality refers to the number of tuples of relation because cardinality represents the number of tuples in a relation.</p><p><strong>To understand it in more detail, consider the following given example:</strong></p><p>Suppose we have a relation (or table) that contains 30 tuples (or Rows) and four columns, so the cardinality of our relation will be 30.</p></div><hr/><p class="pq">24) Which one of the following is a type of Data Manipulation Command?</p><ol class="pointsa"><li>Create</li><li>Alter</li><li>Delete</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(24)"><span id="btntext24">Show Answer</span></button><button class="workspace" onclick="showworkspace(24)"><span id="btntext24">Workspace</span></button><div id="workspace24"> </div><div class="testanswer" id="answer24"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In data manipulation language, the command like select, insert, update, and delete is used to manipulate the information (or data, records), for example create a table, update table delete table, etc. Therefore the correct answer is C.</p></div><hr/><p class="pq">25) Which of the following command is a type of Data Definition language command?</p><ol class="pointsa"><li>Create</li><li>Update</li><li>Delete</li><li>Merge</li></ol><button class="showanswer" onclick="showhide(25)"><span id="btntext25">Show Answer</span></button><button class="workspace" onclick="showworkspace(25)"><span id="btntext25">Workspace</span></button><div id="workspace25"> </div><div class="testanswer" id="answer25"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The Data definition language is generally used to maintain or define the structure of the database. For example, creating a table, drop table, alter table. In short, we can say that the command of data definition languages is used to work on the table's schemas inside the database.</p></div><hr/><p class="pq">26) Which of the following is a top-down approach in which the entity's higher level can be divided into two lower sub-entities?</p><ol class="pointsa"><li>Aggregation</li><li>Generalization</li><li>Specialization</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(26)"><span id="btntext26">Show Answer</span></button><button class="workspace" onclick="showworkspace(26)"><span id="btntext26">Workspace</span></button><div id="workspace26"> </div><div class="testanswer" id="answer26"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In specialization, the top-down approach is used, and it is apposite to the generalization.</p><p>In the specialization, the higher-level entity can be divided into sub lower entities. It is generally used for identifying the subset of an entity set which share the distinguishing characteristics.</p><p><strong>To understand it more clearly, consider the following example:</strong></p><p>Suppose you have an entity, e.g., A vehicle. So through the specialization, you can be divided further into sub-entities like two-wheelers and four-wheelers. Therefore the correct answer is C.</p></div><hr/><p class="pq">27) In which one of the following, the multiple lower entities are grouped (or combined) together to form a single higher-level entity?</p><ol class="pointsa"><li>Specialization</li><li>Generalization</li><li>Aggregation</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(27)"><span id="btntext27">Show Answer</span></button><button class="workspace" onclick="showworkspace(27)"><span id="btntext27">Workspace</span></button><div id="workspace27"> </div><div class="testanswer" id="answer27"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong></p><p>The bottom-up approach is used in the generalization. The several lower-level sub-entities are grouped together to make an individual higher-level entity. In short, we can say that it is totally the opposite of specialization. To understand it more clearly, consider the following example:</p><p>Example</p><p>Suppose you have several lower entities like bus, car, motorbike etc. So, in order to make a more generalize (or higher level ) entity, you can combine them under a new higher-level entity such as a vehicle.</p></div><hr/><p class="pq">28) In a relation database, every tuples divided into the fields are known as the______.</p><ol class="pointsa"><li>Queries</li><li>Domains</li><li>Relations</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(28)"><span id="btntext28">Show Answer</span></button><button class="workspace" onclick="showworkspace(28)"><span id="btntext28">Workspace</span></button><div id="workspace28"> </div><div class="testanswer" id="answer28"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> In a database, the number of rows inside a table is known as tuples, and if we further divide those tuples (or rows) into those fields, they become the domains. So the correct answer will be B.</p></div><hr/><p class="pq">29) The term "TCL" stands for_____.</p><ol class="pointsa"><li>Ternary Control Language</li><li>Transmission Control Language</li><li>Transaction Central Language</li><li>Transaction Control Language</li></ol><button class="showanswer" onclick="showhide(29)"><span id="btntext29">Show Answer</span></button><button class="workspace" onclick="showworkspace(29)"><span id="btntext29">Workspace</span></button><div id="workspace29"> </div><div class="testanswer" id="answer29"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The term "TCL" refers to the Transaction Control Language, which is another language just like the "DDL" and "DML". The commands like commit, save point, rollback come under the TCL used to control the transactions. Therefore the correct answer will be D.</p></div><hr/><p class="pq">30) In the relational table, which of the following can also be represented by the term "attribute"?</p><ol class="pointsa"><li>Entity</li><li>Row</li><li>Column</li><li>Both B &amp;C</li></ol><button class="showanswer" onclick="showhide(30)"><span id="btntext30">Show Answer</span></button><button class="workspace" onclick="showworkspace(30)"><span id="btntext30">Workspace</span></button><div id="workspace30"> </div><div class="testanswer" id="answer30"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In the database, the number of rows inside a table is called the tuples, and the numbers of columns are known as the attributes. Therefore the correct answer is C.</p></div><hr/><p class="pq">31) Which of the following refers to the number of attributes in a relation?</p><ol class="pointsa"><li>Degree</li><li>Row</li><li>Column</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(31)"><span id="btntext31">Show Answer</span></button><button class="workspace" onclick="showworkspace(31)"><span id="btntext31">Workspace</span></button><div id="workspace31"> </div><div class="testanswer" id="answer31"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The column inside the table is called the attribute, and the total number of attributes inside the table is called the degree. So, here as we can see, degree refers to the number of attributes in a relation. Therefore the correct answer is C.</p></div><hr/><p class="pq">32) Which of the following is used in the application programs to request data from the database management system?</p><ol class="pointsa"><li>Data Manipulation language</li><li>Data Definition Language</li><li>Data Control Language</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(32)"><span id="btntext32">Show Answer</span></button><button class="workspace" onclick="showworkspace(32)"><span id="btntext32">Workspace</span></button><div id="workspace32"> </div><div class="testanswer" id="answer32"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> To fetch data from the database management system, generally, the "select" statement is used. Therefore, the Data Manipulation Language is used in the application programs while requesting the data from the database management system.</p></div><hr/><p class="pq">33) Which one of the following command is used to delete the existing row in a table?</p><ol class="pointsa"><li>Delete</li><li>Update</li><li>Insert</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(33)"><span id="btntext33">Show Answer</span></button><button class="workspace" onclick="showworkspace(33)"><span id="btntext33">Workspace</span></button><div id="workspace33"> </div><div class="testanswer" id="answer33"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> To delete an existing row in a table the generally, the "delete" command is used. The "delete" command is one of the commands that belong to the Data manipulation language.</p></div><hr/><p class="pq">34) Which of the following commands is used to save any transaction permanently into the database?</p><ol class="pointsa"><li>Commit</li><li>Rollback</li><li>Savepoint</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(34)"><span id="btntext34">Show Answer</span></button><button class="workspace" onclick="showworkspace(34)"><span id="btntext34">Workspace</span></button><div id="workspace34"> </div><div class="testanswer" id="answer34"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The Transaction Control Language is used while working with the transactions. To save any transaction permanently into the database generally, the "commit" command is used, by which any changes get reflected permanently into the database, and they become irreversible.</p></div><hr/><p class="pq">35) Which one of the following commands is used for removing (or deleting) a relation forms the SQL database?</p><ol class="pointsa"><li>Delete</li><li>Drop</li><li>Remove</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(35)"><span id="btntext35">Show Answer</span></button><button class="workspace" onclick="showworkspace(35)"><span id="btntext35">Workspace</span></button><div id="workspace35"> </div><div class="testanswer" id="answer35"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> To removing( or deleting) a relation, the "drop" command is used instead of delete because here we are working on the objects of the database. So, to maintain the objects of a database, the Data definition language is used. Therefore the "drop" command is used to delete a relation form a database instead of using the "delete" command.</p></div><hr/><p class="pq">36) Which one of the following commands is used to restore the database to the last committed state?</p><ol class="pointsa"><li>Savepoint</li><li>Rollback</li><li>Commit</li><li>Both A &amp; B</li></ol><button class="showanswer" onclick="showhide(36)"><span id="btntext36">Show Answer</span></button><button class="workspace" onclick="showworkspace(36)"><span id="btntext36">Workspace</span></button><div id="workspace36"> </div><div class="testanswer" id="answer36"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> As we all know that while working with the Transactions, the Transaction Control Language is used. To restore the database to the last committed state ( or to undo the latest changes), the "rollback" command is used that belongs to the Transaction Control Language.</p></div><hr/><p class="pq">37) The database management system can be considered as the collection of ______ that enables us to create and maintain the database.</p><ol class="pointsa"><li>Translators</li><li>Programs</li><li>Keys</li><li>Language activity</li></ol><button class="showanswer" onclick="showhide(37)"><span id="btntext37">Show Answer</span></button><button class="workspace" onclick="showworkspace(37)"><span id="btntext37">Workspace</span></button><div id="workspace37"> </div><div class="testanswer" id="answer37"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The Database management system can also considered as the set of programs that enables users to create and maintain the database.</p></div><hr/><p class="pq">38) The term "DFD" stands for?</p><ol class="pointsa"><li>Data file diagram</li><li>Data flow document</li><li>Data flow diagram</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(38)"><span id="btntext38">Show Answer</span></button><button class="workspace" onclick="showworkspace(38)"><span id="btntext38">Workspace</span></button><div id="workspace38"> </div><div class="testanswer" id="answer38"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> The term"DFD" stands for the Data Flow Diagram, and to represent the flow of the data( or information), the data flow diagram is used. The data flow diagram also helps in understanding how the data is managed in the application. Therefore the correct answer is C.</p></div><hr/><p class="pq">39) Which of the following refers collection of the information stored in a database at a specific time?</p><ol class="pointsa"><li>Independence</li><li>Instance of the database</li><li>Schema</li><li>Data domain</li></ol><button class="showanswer" onclick="showhide(39)"><span id="btntext39">Show Answer</span></button><button class="workspace" onclick="showworkspace(39)"><span id="btntext39">Workspace</span></button><div id="workspace39"> </div><div class="testanswer" id="answer39"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The collection of data (or information) stored in a database at a particular moment is known as the instance of the database. Therefore the correct answer is B.</p></div><hr/><p class="pq">40) The term "SQL" stands for</p><ol class="pointsa"><li>Standard query language</li><li>Sequential query language</li><li>Structured query language</li><li>Server-side query language</li></ol><button class="showanswer" onclick="showhide(40)"><span id="btntext40">Show Answer</span></button><button class="workspace" onclick="showworkspace(40)"><span id="btntext40">Workspace</span></button><div id="workspace40"> </div><div class="testanswer" id="answer40"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> The term "SQL" stands for the structured query language, which is one of the most widely, used programming languages for relational databases. It can also be used for managing and organizing data in all sorts of systems in which different data relationships exist. Therefore the correct answer is C.</p></div><hr/><p class="pq">41) The term "Data independence" refers to____</p><ol class="pointsa"><li>Data is defined separately and not included in the programs</li><li>Programs are not dependent on the logical attributes of the data</li><li>Programs are not dependent on the physical attributes of the data</li><li>Both B &amp; C</li></ol><button class="showanswer" onclick="showhide(41)"><span id="btntext41">Show Answer</span></button><button class="workspace" onclick="showworkspace(41)"><span id="btntext41">Workspace</span></button><div id="workspace41"> </div><div class="testanswer" id="answer41"><p><strong>Answer:</strong></p><p><strong>Explanation:</strong> The term "Data independence" refers that the program should not be dependent on either the logical attributes of data or physical attributes of data.</p></div><hr/><p class="pq">42) What is the relation calculus?</p><ol class="pointsa"><li>It is a kind of procedural language</li><li>It is a non-procedural language</li><li>It is a high-level language</li><li>It is Data Definition language</li></ol><button class="showanswer" onclick="showhide(42)"><span id="btntext42">Show Answer</span></button><button class="workspace" onclick="showworkspace(42)"><span id="btntext42">Workspace</span></button><div id="workspace42"> </div><div class="testanswer" id="answer42"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> In database management systems, relation calculus is a type of non-procedural query language that describes what data needs to be retrieved. However, it does not explain how to retrieve the data.</p></div><hr/><p class="pq">43) Which one of the following refers to the total view of the database content?</p><ol class="pointsa"><li>Conceptual view</li><li>Physical view</li><li>Internal view</li><li>External view</li></ol><button class="showanswer" onclick="showhide(43)"><span id="btntext43">Show Answer</span></button><button class="workspace" onclick="showworkspace(43)"><span id="btntext43">Workspace</span></button><div id="workspace43"> </div><div class="testanswer" id="answer43"><p><strong>Answer:</strong> A</p><p><strong>Explanation:</strong> The conceptual view refers to the total view of the content available in the database. Therefore the correct answer is A.</p></div><hr/><p class="pq">44) For what purpose the DML is provided?</p><ol class="pointsa"><li>Addition of new structure in the database</li><li>Manipulation &amp; processing of the database</li><li>Definition of the physical structure of the database system</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(44)"><span id="btntext44">Show Answer</span></button><button class="workspace" onclick="showworkspace(44)"><span id="btntext44">Workspace</span></button><div id="workspace44"> </div><div class="testanswer" id="answer44"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The term "DML" refers to the data manipulation language, which is commonly used to perform basic operations such as insert data, delete, and update data in a database. So the correct answer will be B.</p></div><hr/><p class="pq">45) The term "ODBC" stands for_____</p><ol class="pointsa"><li>Oral database connectivity</li><li>Oracle database connectivity</li><li>Open database connectivity</li><li>Object database connectivity</li></ol><button class="showanswer" onclick="showhide(45)"><span id="btntext45">Show Answer</span></button><button class="workspace" onclick="showworkspace(45)"><span id="btntext45">Workspace</span></button><div id="workspace45"> </div><div class="testanswer" id="answer45"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> The term "ODBC" refers to the Open Database Connectivity that is a SQL based programming interface introduced by Microsoft.</p></div><hr/><p class="pq">46) The architecture of a database can be viewed as the ________</p><ol class="pointsa"><li>One level</li><li>Two-level</li><li>Three-level</li><li>Four level</li></ol><button class="showanswer" onclick="showhide(46)"><span id="btntext46">Show Answer</span></button><button class="workspace" onclick="showworkspace(46)"><span id="btntext46">Workspace</span></button><div id="workspace46"> </div><div class="testanswer" id="answer46"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> A database's architecture can be viewed as the three levels of abstraction that are named as the internal level, external level, and the conceptual level. Therefore the correct answer is C.</p></div><hr/><p class="pq">47) In the relation model, the relation are generally termed as ________</p><ol class="pointsa"><li>Tuples</li><li>Attributes</li><li>Rows</li><li>Tables</li></ol><button class="showanswer" onclick="showhide(47)"><span id="btntext47">Show Answer</span></button><button class="workspace" onclick="showworkspace(47)"><span id="btntext47">Workspace</span></button><div id="workspace47"> </div><div class="testanswer" id="answer47"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> In the relation model, the relations are also referred to as the tables because the relations are considered as the technical name of the table. So the correct answer is D.</p></div><hr/><p class="pq">48) The Database Management Query language is generally designed for the _____</p><ol class="pointsa"><li>Support end-users who use English like commands</li><li>Specifying the structure of the database</li><li>Support in the development of the complex applications software</li><li>All of the above</li></ol><button class="showanswer" onclick="showhide(48)"><span id="btntext48">Show Answer</span></button><button class="workspace" onclick="showworkspace(48)"><span id="btntext48">Workspace</span></button><div id="workspace48"> </div><div class="testanswer" id="answer48"><p><strong>Answer:</strong> D</p><p><strong>Explanation:</strong> The database management query language is generally designed by keeping in mind that it must support the end-users who are familiar with the English-like commands. It should also boost the process of development of the complex applications software and helps in specifying the structure of the database.</p></div><hr/><p class="pq">49) Which of the following keys is generally used to represents the relationships between the tables?</p><ol class="pointsa"><li>Primary key</li><li>Foreign key</li><li>Secondary key</li><li>None of the above</li></ol><button class="showanswer" onclick="showhide(49)"><span id="btntext49">Show Answer</span></button><button class="workspace" onclick="showworkspace(49)"><span id="btntext49">Workspace</span></button><div id="workspace49"> </div><div class="testanswer" id="answer49"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> To represent the relationships between the various tables in the database, generally, the foreign key is used. Therefore the correct answer is the foreign key.</p></div><hr/><p class="pq">50) Which of the following levels is considered as the level closed to the end-users?</p><ol class="pointsa"><li>Internal Level</li><li>External Level</li><li>Conceptual Level</li><li>Physical Level</li></ol><button class="showanswer" onclick="showhide(50)"><span id="btntext50">Show Answer</span></button><button class="workspace" onclick="showworkspace(50)"><span id="btntext50">Workspace</span></button><div id="workspace50"> </div><div class="testanswer" id="answer50"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The database's external level is the one and only level that is considered the closest level to the end-users. So the correct answer will be the B.</p></div><hr/><p class="pq">51) A computer security protocol for logging-in can be considered as the example of the ______ component of an information system.</p><ol class="pointsa"><li>Data</li><li>Software</li><li>Procedure</li><li>Hardware</li></ol><button class="showanswer" onclick="showhide(51)"><span id="btntext51">Show Answer</span></button><button class="workspace" onclick="showworkspace(51)"><span id="btntext51">Workspace</span></button><div id="workspace51"> </div><div class="testanswer" id="answer51"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> A computer security protocol for logging-in can be considered as the procedure component of an information system. Therefore the correct answer is C.</p></div><hr/><p class="pq">52) Which one of the following keyword is used to find out the number of values in a column?</p><ol class="pointsa"><li>TOTAL</li><li>COUNT</li><li>SUM</li><li>ADD</li></ol><button class="showanswer" onclick="showhide(52)"><span id="btntext52">Show Answer</span></button><button class="workspace" onclick="showworkspace(52)"><span id="btntext52">Workspace</span></button><div id="workspace52"> </div><div class="testanswer" id="answer52"><p><strong>Answer:</strong> B</p><p><strong>Explanation:</strong> The "COUNT" keyword is used to find the total number of values inside a column. So whenever a user wants to find the total values in a column, he can use the keyword "COUNT".</p></div><hr/><p class="pq">53) Which one of the following is commonly used to define the overall design of the database?</p><ol class="pointsa"><li>Application program</li><li>Data definition language</li><li>Schema</li><li>Source code</li></ol><button class="showanswer" onclick="showhide(53)"><span id="btntext53">Show Answer</span></button><button class="workspace" onclick="showworkspace(53)"><span id="btntext53">Workspace</span></button><div id="workspace53"> </div><div class="testanswer" id="answer53"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> In order to define the overall design of the database, generally, the schema is used. Therefore the correct answer is C.</p></div><hr/><p class="pq">54) Which one of the following commands is used to modify a column inside a table?</p><ol class="pointsa"><li>Drop</li><li>Update</li><li>Alter</li><li>Set</li></ol><button class="showanswer" onclick="showhide(54)"><span id="btntext54">Show Answer</span></button><button class="workspace" onclick="showworkspace(54)"><span id="btntext54">Workspace</span></button><div id="workspace54"> </div><div class="testanswer" id="answer54"><p><strong>Answer:</strong> C</p><p><strong>Explanation:</strong> To make manipulations in a column of a specific table, the "alter" command is used. To understand it more clearly, consider the following example:</p></div><hr/><div class="nexttopicdiv"><span class="nexttopictext">Next Topic</span><span class="nexttopiclink"><a href="dbms-tutorial">DBMS Tutorial</a></span></div> <div id="bottomnext"><a class="next" href="dbms-sql-cursors" style="float:left">← prev</a> <a class="next" href="dbms-tutorial" style="float:right">next →</a></div><br> </br></br></td></tr></tbody></table></div><br/></div><div class="related-posts-container"><h2 class="h3">Related Posts</h2><ul class="related-posts-list"><li><a class="related-post-item" href="bootstrap-4-mcq"><h3 class="h3">Bootstrap 4 MCQ</h3><p class="related-post-content">Bootstrap 4 - Multiple Choice Questions 1) Which of the following statements is/are correct about Bootstrap 4? It provides a free front - end framework It is a completely open - source product It gives the ability to create responsive designs All of the above Show Answer Workspace Answer: d. All of the above Explanation:...</p><p class="reading-time"><i aria-hidden="true" class="fa fa-clock-o"></i> 15 min read <span class="arrow-position"><svg fill="currentColor" height="1.3rem" stroke="currentColor" stroke-width="0" viewbox="0 0 512 512" width="1.3rem" xmlns="http://www.w3.org/2000/svg"><path d="M295.6 163.7c-5.1 5-5.1 13.3-.1 18.4l60.8 60.9H124.9c-7.1 0-12.9 5.8-12.9 13s5.8 13 12.9 13h231.3l-60.8 60.9c-5 5.1-4.9 13.3.1 18.4 5.1 5 13.2 5 18.3-.1l82.4-83c1.1-1.2 2-2.5 2.7-4.1.7-1.6 1-3.3 1-5 0-3.4-1.3-6.6-3.7-9.1l-82.4-83c-4.9-5.2-13.1-5.3-18.2-.3z"></path></svg></span></p></a></li><li><a class="related-post-item" h